# Single source of truth for the build plan: every Claude Code session, its dependencies,
# what to give it and what it hands on. Generates the doc tables and the kit briefs.

WAVES = {
    0: "Wave 0 · Decide and freeze",
    1: "Wave 1 · Foundation",
    2: "Wave 2 · Shared core",
    3: "Wave 3 · First real data, and the Meta review build",
    4: "Wave 4 · YouTube, X, and Facebook in development mode",
    5: "Wave 5 · Approval-gated platforms and the client portal",
    6: "Wave 6 · Insight layer",
    7: "Wave 7 · Amber vendor routes (optional)",
}

SIZE = {"S": "one sitting", "M": "1 to 2 days with review", "L": "3 to 5 days with review"}

def S(id, title, wave, track, size, builds, needs=(), give=(), produces=(), alongside=(),
      services=(), anytime=None, deadline=None, traps=(), human=None, kind="service", critical=False):
    return dict(id=id, title=title, wave=wave, track=track, size=size, builds=builds, needs=list(needs),
                give=list(give), produces=list(produces), alongside=list(alongside), services=list(services),
                anytime=anytime, deadline=deadline, traps=list(traps), human=human, kind=kind, critical=critical)

