EXTRA_ALONGSIDE = {
    "X7": ["X1", "X2", "X3"], "X4": ["X5", "X6"], "X5": ["X6"],
    "YT5": ["YT8"], "YT6": ["YT7", "YT8"], "YT7": ["YT8"],
    "FB6": ["FB3", "FB4", "FB5"],
    "N7": ["N3", "N4", "N5"], "N8": ["N7"],
    "IG2": ["IG3"],
}
_by = {x["id"]: x for x in SESSIONS}
for a, bs in EXTRA_ALONGSIDE.items():
    for b in bs:
        if b not in _by[a]["alongside"]: _by[a]["alongside"].append(b)
# make alongside symmetric
for x in SESSIONS:
    for b in list(x["alongside"]):
        if b in _by and x["id"] not in _by[b]["alongside"]:
            _by[b]["alongside"].append(x["id"])

BY_ID = {s["id"]: s for s in SESSIONS}
